#!/usr/bin/env python3
"""Generate the pinned runtime RBK interface catalogue from reviewed supplier evidence."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
REFERENCE = Path(__file__).with_name('rbk-interfaces.json')
TARGET = ROOT / 'machinekit/haxe/src/machinekit/assembly/RbkMountData.hx'


def render(data):
    payload = json.dumps(data, separators=(',', ':'), ensure_ascii=True)
    return ('package machinekit.assembly;\n\n'
            '// Generated by python3 tools/suppliers/rbk_interfaces.py --write-haxe.\n'
            '// Review tools/suppliers/rbk-interfaces.json before changing pinned interfaces.\n'
            'class RbkMountData {\n    public static function text():String return '
            + json.dumps(payload) + ';\n}\n')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--write-haxe', action='store_true')
    args = parser.parse_args()
    rendered = render(json.loads(REFERENCE.read_text()))
    if args.write_haxe:
        TARGET.write_text(rendered)
        print(TARGET)
    elif TARGET.read_text() != rendered:
        raise SystemExit('RBK runtime metadata differs from reviewed reference; regenerate explicitly')
    else:
        print('RBK runtime metadata matches reviewed reference')
